        FactorialCalculator calc = new FactorialCalculator();

        int chequeCount = 5;  // Rajesh's batch (SAV2001)
        BigInteger arrangements = calc.factorial(chequeCount);
        log.info(() -> "Rajesh SAV2001: " + chequeCount + " cheques can be processed in "
                + arrangements + " distinct orders");

        // Zero case: an empty batch has exactly one ordering.
        log.info(() -> "Empty batch 0! = " + calc.factorial(0));
    }
}

// ─── Would be in FactorialCalculator.java in a real project ───
class FactorialCalculator {
    // result = 1; for i = 1..N { result = result * i }  -> N!
    BigInteger factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Factorial undefined for negative n: " + n);
        }
        BigInteger result = BigInteger.ONE;          // empty product = 1 (handles 0!)
        for (int i = 1; i <= n; i++) {               // loop while i <= N
            result = result.multiply(BigInteger.valueOf(i));  // BigInteger: no overflow
        }
        return result;
    }
}

