// ─── Would be in TriangleValidator.java in a real project ───
class TriangleValidator {
    // Valid iff A+B>C AND B+C>A AND C+A>B (strict). compareTo for exact numeric comparison.
    boolean canFormTriangle(BigDecimal a, BigDecimal b, BigDecimal c) {
        if (a == null || b == null || c == null) {
            throw new IllegalArgumentException("Lengths must not be null");
        }
        if (a.signum() <= 0 || b.signum() <= 0 || c.signum() <= 0) {
            return false;  // non-positive length cannot be a side
        }
        boolean ab = a.add(b).compareTo(c) > 0;  // A + B > C
        boolean bc = b.add(c).compareTo(a) > 0;  // B + C > A
        boolean ca = c.add(a).compareTo(b) > 0;  // C + A > B
        return ab && bc && ca;
    }
}

