class MaxFinder {
    // Seed max with the FIRST value (not 0), then scan the rest. compareTo for money.
    BigDecimal largest(List<BigDecimal> amounts) {
        if (amounts == null || amounts.isEmpty()) {
            throw new IllegalArgumentException("Need at least one amount");
