        BigDecimal max = amounts.get(0);            // read first into max
        for (int i = 1; i < amounts.size(); i++) {  // i = 2..N (0-based 1..size-1)
            BigDecimal x = amounts.get(i);
            if (x.compareTo(max) > 0) {             // x > max ?
                max = x;                            // update running maximum
