class PrimeChecker {
    // Trial division up to sqrt(n): test i while i*i <= n; break on first divisor.
    boolean isPrime(int n) {
        if (n < 2) {
            return false;                    // 0, 1, negatives are not prime
        }
        for (int i = 2; (long) i * i <= n; i++) {  // only up to sqrt(n)
            if (n % i == 0) {                // i divides n evenly
                return false;                // composite -> break out, answer settled
            }
        }
        return true;                         // no divisor found -> prime
    }
}

