package com.bank.dsa;

import java.util.logging.*;

// Runnable demo: sum even-numbered tier fees from 20 to 40 inclusive.
public class SumEvensRangeDemo {
    private static final Logger log = Logger.getLogger(SumEvensRangeDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RangeEvenSum calc = new RangeEvenSum();

        long viaLoop    = calc.sumEvens(20, 40);
        long viaFormula = calc.sumEvensFormula(20, 40);
        log.info(() -> "Even tier fee sum 20..40 via loop    = " + viaLoop);
        log.info(() -> "Even tier fee sum 20..40 via formula = " + viaFormula);
    }
}

// ─── Would be in RangeEvenSum.java in a real project ───
class RangeEvenSum {
    // Loop: start at first even >= lo, step by 2 up to hi inclusive.
    long sumEvens(int lo, int hi) {
        if (lo > hi) {
            throw new IllegalArgumentException("lo must be <= hi");
        }
        long sum = 0;                                   // additive identity
        int start = (lo % 2 == 0) ? lo : lo + 1;        // first even >= lo
        for (int i = start; i <= hi; i = i + 2) {       // step by 2 -> only evens
            sum = sum + i;
        }
        return sum;
    }

    // Closed form: terms × average of first and last term.
    long sumEvensFormula(int lo, int hi) {
        if (lo > hi) {
            throw new IllegalArgumentException("lo must be <= hi");
        }
        int first = (lo % 2 == 0) ? lo : lo + 1;        // first even
        int last  = (hi % 2 == 0) ? hi : hi - 1;        // last even
        if (first > last) {
            return 0;                                   // no even numbers in range
        }
        long terms = (last - first) / 2 + 1;            // inclusive count
        return terms * (first + last) / 2;              // count × average
    }
}

